package com.example.lab11; import android.content.Intent; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { EditText etName,etRollNo,etCourse; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etName=findViewById(R.id.etName);etRollNo=findViewById(R.id.etRollNo);etCourse=findViewById(R.id.etCourse);Button btn=findViewById(R.id.btnSubmit);btn.setOnClickListener(v->{Intent i=new Intent(MainActivity.this,SecondActivity.class);i.putExtra("name",etName.getText().toString());i.putExtra("rollNo",etRollNo.getText().toString());i.putExtra("course",etCourse.getText().toString());startActivity(i);});} }